// App shell served from the device, so opening the app does not wait for a
// Korea -> workers.dev round trip per file.
//
// Every deploy produces a new ASSET_HASH (computed by server/build-assets.mjs
// from all served files), which makes this file byte-different, so browsers
// install the new version in the background. The new worker waits; pwa.js
// switches to it (and reloads) only when no exam or practice is on screen.

// BUILD:START (generated by server/build-assets.mjs, do not edit by hand)
const ASSET_HASH = '033190894a9ebd06';
const PRECACHE = ["/app.bundle.css","/app.js","/boot-guard.js","/icon.svg","/","/manifest.webmanifest","/modules/battle.js","/modules/character.js","/modules/core.js","/modules/pet-moments.js","/modules/sessions.js","/modules/student.js","/modules/teacher.js","/modules/ui.js","/practice-enhancements.js","/pwa.js","/student-enhancements.js","/sumus-logo-green.svg"];
// BUILD:END

const CACHE = `sumus-voca-${ASSET_HASH}`;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    // addAll is atomic: if any file fails, this version is not installed and
    // the previous one keeps serving.
    const cache = await caches.open(CACHE);
    await cache.addAll(PRECACHE.map(url => new Request(url, { cache: 'reload' })));
    // v13.50.0 cached the page from /index.html, which Cloudflare answers with a
    // 307 to /, and a redirected response cannot open the app. Replace such a
    // worker at once: pwa.js, which normally triggers the switch, never runs
    // on a page that failed to open.
    for (const name of await caches.keys()) {
      if (name === CACHE || !name.startsWith('sumus-voca-')) continue;
      const page = await (await caches.open(name)).match('/index.html');
      if (page?.redirected) { await self.skipWaiting(); break; }
    }
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith('sumus-voca-') && name !== CACHE).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // Never cache authenticated API data, exam drafts, scores, or student records.
  if (url.pathname.startsWith('/api/')) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      // A redirected response must never answer a navigation (the browser
      // rejects it and the app does not open).
      const cached = await caches.match('/', { cacheName: CACHE });
      if (cached && !cached.redirected) return cached;
      return fetch(req);
    })());
    return;
  }

  event.respondWith((async () => {
    // ignoreSearch: the page asks for /app.js?v=..., the cache stores /app.js.
    const cached = await caches.match(req, { cacheName: CACHE, ignoreSearch: true });
    if (cached) return cached;
    const response = await fetch(req);
    // Files outside the precache (teacher tools, grammar data) are kept for
    // this version once used.
    if (response.ok && response.type === 'basic' && !response.redirected) {
      const cache = await caches.open(CACHE);
      cache.put(url.pathname, response.clone());
    }
    return response;
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});
